d:#09131f;border-radius:11px}.weather-metric span{display:block;color:#71849d;font-size:.58rem}.weather-metric strong{display:block;font-size:1rem;margin-top:5px}.hourly-strip{display:grid;grid-template-columns:repeat(6,1fr);gap:7px;margin-top:14px}.hour{padding:9px;text-align:center;background:#101d2e;border-radius:9px}.hour span{display:block;color:#73869f;font-size:.55rem}.hour strong{font-size:.68rem}.weather-chart{padding:19px}.chart-box{height:310px}.error{color:#ff7a91;font-size:.69rem;margin-bottom:10px}@media(max-width:950px){.weather-hero{grid-template-columns:1fr}.hourly-strip{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){.location-bar{grid-template-columns:1fr}.weather-metrics{grid-template-columns:1fr}.weather-head{align-items:flex-start;flex-direction:column}}</style>
<div class="weather-page"><header class="weather-head"><div><div class="kicker">PORT WEATHER OPERATIONS</div><h1>Maritime Weather Command</h1><p>Cuaca operasional berbasis koordinat pelabuhan melalui Open-Meteo.</p></div><div class="live"><i></i>Live forecast feed</div></header><div class="location-bar"><select id="port">@foreach($ports as $port)<option value="{{ $port->latitude }},{{ $port->longitude }}" data-name="{{ $port->port_name }}" data-country="{{ $port->country_name }}">{{ $port->port_name }} — {{ $port->country_name }}</option>@endforeach</select><button onclick="loadWeather()">↻ Refresh weather</button></div><div class="error" id="error"></div><section class="weather-hero"><article class="current-weather"><div class="weather-icon" id="weatherIcon">◌</div><span id="weatherLocation">Selected port</span><strong id="temperature">—</strong><p id="condition">Mengambil kondisi terbaru...</p><div class="risk-line"><span>Operational weather risk</span><b id="risk">—</b></div></article><article class="forecast-panel"><h2>Current Operational Metrics</h2><div class="weather-metrics"><div class="weather-metric"><span>PRECIPITATION</span><strong id="rain">—</strong></div><div class="weather-metric"><span>WIND SPEED</span><strong id="wind">—</strong></div><div class="weather-metric"><span>RELATIVE HUMIDITY</span><strong id="humidity">—</strong></div></div><div class="hourly-strip" id="hourlyStrip"></div></article></section><section class="weather-chart"><h2>24-Hour Wind & Precipitation Outlook</h2><div class="chart-box"><canvas id="weatherChart"></canvas></div></section></div>
<script>let weatherChart;const weatherCodes={0:['☀','Cerah'],1:['🌤','Cerah berawan'],2:['⛅','Berawan'],3:['☁','Mendung'],45:['🌫','Berkabut'],51:['🌦','Gerimis'],61:['🌧','Hujan'],63:['🌧','Hujan sedang'],65:['⛈','Hujan lebat'],80:['🌦','Hujan lokal'],95:['⛈','Badai petir']};async function loadWeather(){const select=document.getElementById('port'),[latitude,longitude]=select.value.split(','),option=select.options[select.selectedIndex];error.textContent='';weatherLocation.textContent=option.dataset.name+' · '+option.dataset.country;try{const response=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${latitude}&longitude=${longitude}&current=temperature_2m,relative_humidity_2m,precipitation,weather_code,wind_speed_10m&hourly=temperature_2m,wind_speed_10m,precipitation_probability,precipitation&forecast_days=1&timezone=auto`);if(!response.ok)throw new Error();const data=await response.json(),c=data.current,weather=weatherCodes[c.weather_code]||['◌','Kondisi kode '+c.weather_code],score=Math.min(100,Math.round(c.wind_speed_10m*1.5+c.precipitation*4));weatherIcon.textContent=weather[0];condition.textContent=weather[1]+' · diperbarui '+c.time.replace('T',' ');temperature.textContent=c.temperature_2m+' °C';rain.textContent=c.precipitation+' mm';wind.textContent=c.wind_speed_10m+' km/h';humidity.textContent=c.relative_humidity_2m+'%';risk.textContent=score+'/100 · '+(score>=65?'High':score>=35?'Medium':'Low');hourlyStrip.innerHTML=[0,4,8,12,16,20].map(i=>`<div class="hour"><span>${data.hourly.time[i].slice(11)}</span><strong>${data.hourly.temperature_2m[i]}°</strong><span>${data.hourly.precipitation_probability[i]}% rain</span></div>`).join('');weatherChart?.destroy();weatherChart=new Chart(document.getElementById('weatherChart'),{type:'line',data:{labels:data.hourly.time.map(x=>x.slice(11)),datasets:[{label:'Wind km/h',data:data.hourly.wind_speed_10m,borderColor:'#35e6b1',backgroundColor:'rgba(53,230,177,.12)',fill:true,tension:.38},{label:'Rain mm',data:data.hourly.precipitation,borderColor:'#37c8ff',backgroundColor:'rgba(55,200,255,.1)',fill:true,tension:.38,yAxisID:'y1'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{color:'#9bacc1',usePointStyle:true}}},scales:{x:{grid:{display:false},ticks:{color:'#72849d',maxTicksLimit:12}},y:{grid:{color:'rgba(130,150,175,.09)'},ticks:{color:'#72849d'}},y1:{position:'right',grid:{display:false},ticks:{color:'#72849d'}}}}})}catch(e){error.textContent='Open-Meteo tidak dapat dihubungi. Coba beberapa saat lagi.'}}document.getElementById('port').addEventListener('change',loadWeather);loadWeather();</script>
